import{_ as s,o as i,c as a,a3 as t}from"./chunks/framework.16qmHapV.js";const k=JSON.parse('{"title":"Installation","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md"}'),n={name:"guide/installation.md"};function l(h,e,d,r,o,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>These instructions start in the PAI project directory: the directory containing <code>package.json</code>, <code>src/</code>, <code>spec/</code>, and <code>content/</code>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Required for</th></tr></thead><tbody><tr><td>Node.js 24 or later, with npm</td><td>Server, publication client, file CLI, builds, and service checks</td></tr><tr><td>Python 3</td><td>Independent ZIP checks in the file and specification tests</td></tr><tr><td>POSIX shell</td><td>The documented commands; use a macOS/Linux shell or a WSL shell on Windows</td></tr><tr><td>A modern browser</td><td>Reading and editing <code>.pai.html</code></td></tr></tbody></table><p>Dependency installation downloads the versions recorded in the two <code>package-lock.json</code> files. Running the built editor locally and processing existing files do not require an external model or a PAI account.</p><h2 id="install-and-build" tabindex="-1">Install and build <a class="header-anchor" href="#install-and-build" aria-label="Permalink to &quot;Install and build&quot;">​</a></h2><p>Clone the repository and enter its directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JacenDu/pai-protocol.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pai-protocol</span></span></code></pre></div><p>For a project-built source archive, extract it and enter <code>pai-content-alpha.2/</code> instead. Before installing or rebuilding that archive, verify its payload:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/verify-package.mjs</span></span></code></pre></div><p>The verifier applies to the project-built archive, which includes <code>MANIFEST.json</code>. Git checkouts and GitHub-generated source downloads do not contain that manifest. Record <code>git rev-parse HEAD</code> when using a checkout, or the supplied archive&#39;s SHA-256 when using a project-built archive.</p><p>Install and build from the project root:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prefix</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The build writes examples to <code>content/dist/</code>. Open <code>content/dist/service.pai.html</code> in a browser to edit a sample. To load another document, choose <strong>新建 → 打开现有文件</strong> (New → Open existing file). The file picker accepts <code>.pai</code> and <code>.pai.html</code>.</p><p>Inspect a sample using the CLI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/dist/event.pai</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/cli.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content/dist/event.pai</span></span></code></pre></div><h2 id="run-the-local-trial" tabindex="-1">Run the local trial <a class="header-anchor" href="#run-the-local-trial" aria-label="Permalink to &quot;Run the local trial&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trial</span></span></code></pre></div><p>The command starts a content server on <code>127.0.0.1:4753</code>, publishes the event sample, and prints its reading URL. It creates or reuses a local publisher credential and snapshots under <code>.pai-data/example/</code>. Retrying unchanged content keeps the same published version. Ctrl+C stops the server.</p><p>If port 4753 is already occupied, stop the earlier trial or start a separately configured reference server on another port. The <a href="/pai-website/guide/server.html#run-the-reference-server">server guide</a> shows that setup.</p><h2 id="run-the-automated-checks" tabindex="-1">Run the automated checks <a class="header-anchor" href="#run-the-automated-checks" aria-label="Permalink to &quot;Run the automated checks&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span></span></code></pre></div><p>This command builds the editor, then runs file validation and conversion, fixtures and schema rules, publication behavior, and client handling checks. Network tests start temporary servers on loopback addresses. They do not require a running trial or model credentials. The constituent commands remain available as <code>npm --prefix content test</code>, <code>npm run check:spec</code>, and <code>npm run test:content</code>.</p><p>With the trial running in another terminal, check its published document:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/check-service.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4753</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trial-report.json</span></span></code></pre></div><p>The output path must not already exist. This command performs public reads. The JSON report lists the operations checked, failures, and skipped checks. Use the <a href="/pai-website/guide/server.html#check-an-implementation">server guide</a> for write probes and a selected resource.</p><p>List published resources or read the event sample as a client:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/read.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4753</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/read.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4753</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pai:example</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --document</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> event</span></span></code></pre></div><h2 id="check-a-clean-installation" tabindex="-1">Check a clean installation <a class="header-anchor" href="#check-a-clean-installation" aria-label="Permalink to &quot;Check a clean installation&quot;">​</a></h2><p>Use a fresh clone or extract the project-built archive into a new directory, then run the install, build, and automated-check commands above. Start the trial and run the read-only service check. A successful result should include a published sample whose file, structured content, original images, and version metadata agree.</p><p>The installation uses files in that directory. Existing <code>.pai-data/</code>, <code>node_modules/</code>, browser profiles, model logins, and files elsewhere in the development workspace are not prerequisites. Generated runs, published documents, and credentials stay outside version control.</p>`,31)])])}const u=s(n,[["render",l]]);export{k as __pageData,u as default};
